"""Real Whisper transcription on speech generated by Windows text-to-speech.

Opt-in (loads a Whisper model): set RUN_WHISPER_TESTS=1. Uses WHISPER_TEST_MODEL
(default "tiny", fast and small) so it doesn't depend on the app's configured model.
"""

import os
import shutil
import subprocess
import sys

import pytest

from app.services import media, transcription
from app.services.sentences import split_sentences

pytestmark = [
    pytest.mark.integration,
    pytest.mark.skipif(os.environ.get("RUN_WHISPER_TESTS") != "1",
                       reason="set RUN_WHISPER_TESTS=1 to run real Whisper transcription"),
]

SPEECH = ("Welcome to the clip generator test. Today we talk about cooking pasta. "
          "First, boil the water. Then add salt and the pasta.")


@pytest.fixture(scope="module")
def speech_wav(tmp_path_factory):
    if sys.platform != "win32" or shutil.which("powershell") is None:
        pytest.skip("needs Windows text-to-speech")
    raw = tmp_path_factory.mktemp("speech") / "tts.wav"
    script = (
        "Add-Type -AssemblyName System.Speech; "
        "$s = New-Object System.Speech.Synthesis.SpeechSynthesizer; "
        f"$s.SetOutputToWaveFile('{raw}'); $s.Speak('{SPEECH}'); $s.Dispose()"
    )
    subprocess.run(["powershell", "-NoProfile", "-Command", script], check=True, timeout=120)
    return media.extract_audio(raw, raw.with_name("audio.wav"))


def test_real_transcription(speech_wav, monkeypatch):
    monkeypatch.setenv("WHISPER_MODEL", os.environ.get("WHISPER_TEST_MODEL", "tiny"))
    monkeypatch.setenv("WHISPER_LANGUAGE", "en")
    progress: list[float] = []

    result = transcription.transcribe(speech_wav, on_progress=progress.append)

    text = "".join(w.text for w in result.words).lower()
    for keyword in ("clip generator", "pasta", "boil", "water", "salt"):
        assert keyword in text, f"{keyword!r} missing from: {text}"
    assert result.language == "en"
    duration = media.probe(speech_wav).duration_seconds
    starts = [w.start for w in result.words]
    assert starts == sorted(starts)
    assert all(0 <= w.start <= w.end <= duration + 0.5 for w in result.words)
    assert progress and progress[-1] == 1.0

    sentences = split_sentences(result.words)
    assert len(sentences) >= 3
    assert sentences[0].text.lower().startswith("welcome")
